// kzn-logo — single-file build (generated by tools/build-standalone.mjs)
// ---- src/core.js ----
// kzn-logo — core geometry engine. No DOM, no dependencies.
//
// Everything below is measured from the master mark in Figma
// (file "KZN Web", node 170-3040 "Logogrid"): six equal circles composed on a
// 4×4 grid of square cells.
//
// Coordinate system for generated formations:
//   · the grid CELL is the unit of length
//   · the ORIGIN is the grid center — the crosshair the mark orbits
//   · x grows right, y grows down (SVG sense)
//   · gridlines sit at integer offsets from the origin, so a true central
//     crosshair exists at any canvas size or aspect ratio
//
// The construction system, as measured from the static mark:
//   · dot radius R = 0.3875 cells — dot diameter is 0.775 of a cell, exactly.
//     Scale of dot vs. cell is what dictates closeness; it is a constant.
//   · the KERNEL dot's edge passes through the crosshair ("touches the center
//     with its side, from any angle") — its center never sits on it
//   · every other dot sits ON the grid: center on a vertical gridline, and
//     vertically either resting centered on a horizontal gridline, or hanging
//     with its top edge kissing one (the static mark uses both)
//   · no two dots ever touch
//   · distance-to-center grows strictly rank by rank — the gravity falloff
//
// The static mark itself is the sanctioned exception: it carries ~1–2px of
// hand-tuned optical slack over this skeleton (and two rank ties). It is
// therefore stored verbatim, not generated.

/** Dot radius in cell units (31/80 — measured 42.9058px on a 110.7246px cell). */
const R = 0.3875;

/**
 * The canonical static mark ("stable symbol"), exact Figma coordinates in px,
 * cropped to the tight bounding box of the six dots (this crop is the "Logo"
 * component used across the site — aspect ≈ 1.156:1).
 * Dots are in rank order: kernel (closest to center) first.
 */
const MARK = {
  viewBox: [0, 0, 307.2609, 265.7392],
  r: 42.9058,
  cell: 110.7246,
  /** grid-center of the original Logogrid frame, in this crop's coordinates */
  center: [152.2464, 111.2826],
  dots: [
    [153.6304, 156.3986], // kernel — reaching up to the crosshair
    [153.6304, 42.9058],
    [42.9058, 42.9058],
    [264.3551, 42.9058],
    [42.9058, 222.8334],
    [264.3551, 222.8334],
  ],
};

/**
 * The same mark reduced to its rational skeleton, in grid units (center
 * origin): optical slack removed, tangency exact. Used as the resting/initial
 * state of the dynamic logo so the first shuffle departs from the mark itself.
 */
const MARK_IDEAL = {
  w: 4,
  h: 4,
  r: R,
  dots: [
    [0, R], //          kernel: hangs from the crosshair, edge through center
    [0, -1 + R], //     hangs under the upper gridline, center column
    [-1, -1 + R], //    hangs under the upper gridline, left column
    [1, -1 + R], //     hangs under the upper gridline, right column
    [-1, 1], //         rests on the lower gridline, left column
    [1, 1], //          rests on the lower gridline, right column
  ],
};

/** String/number seed → uint32 (xmur3 finalizer). */
function hashSeed(seed) {
  const s = String(seed);
  let h = 1779033703 ^ s.length;
  for (let i = 0; i < s.length; i++) {
    h = Math.imul(h ^ s.charCodeAt(i), 3432918353);
    h = (h << 13) | (h >>> 19);
  }
  h = Math.imul(h ^ (h >>> 16), 2246822507);
  h = Math.imul(h ^ (h >>> 13), 3266489909);
  return (h ^= h >>> 16) >>> 0;
}

/** Deterministic PRNG (mulberry32). Same seed → same formation, everywhere. */
function rng(seed) {
  let a = hashSeed(seed);
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Tunable rules. These four knobs are deliberately exposed — they encode the
 * open design decisions; nothing is baked in. Defaults follow the measured mark.
 */
const defaults = {
  /**
   * How strictly dots sit on the grid:
   *  'construction' — the measured system: centers on vertical gridlines,
   *                   resting on or hanging under horizontal ones (discrete)
   *  'lines'        — centers may slide anywhere along any gridline
   *  'points'       — centers on the grid intersections only (most staccato)
   * The kernel is always the one continuous element: tangent to the
   * crosshair at a free angle.
   */
  placement: 'construction',
  /** Minimum edge-to-edge clearance between dots, in cells ("never touch"). */
  gap: 0.15,
  /** How far toward the canvas reach the outermost rank may sit (0..1). */
  spread: 0.85,
  /** Minimum clearance between a dot's edge and the canvas edge, in cells. */
  edge: 0.05,
  /** Minimum growth of center-distance from one rank to the next, in cells. */
  rankStep: 0.07,
  /** Dot count, kernel included. 6 is the mark; others are decorative modes. */
  count: 6,
  /** Candidate formations scored per generate() call (quality vs. cost). */
  rollouts: 48,
};

const dist = (a, b) => Math.hypot(a[0] - b[0], a[1] - b[1]);
const len = (p) => Math.hypot(p[0], p[1]);

/** Legal center positions for non-kernel dots under the placement rule. */
function candidatePositions(limX, limY, placement, rnd) {
  const out = [];
  const vLines = [];
  const hLines = [];
  for (let i = Math.ceil(-limX); i <= Math.floor(limX); i++) vLines.push(i);
  for (let j = Math.ceil(-limY); j <= Math.floor(limY); j++) hLines.push(j);

  if (placement === 'lines') {
    // continuous slide along gridlines — resampled every call
    const PER_LINE = 7;
    for (const i of vLines)
      for (let k = 0; k < PER_LINE; k++) out.push([i, -limY + rnd() * 2 * limY]);
    for (const j of hLines)
      for (let k = 0; k < PER_LINE; k++) out.push([-limX + rnd() * 2 * limX, j]);
    return out;
  }

  for (const i of vLines) {
    for (let j = Math.ceil(-limY - R); j <= Math.floor(limY); j++) {
      if (j >= -limY) out.push([i, j]); // resting: center on the line
      if (placement === 'construction' && j + R >= -limY && j + R <= limY)
        out.push([i, j + R]); // hanging: top edge kisses the line above
    }
  }
  return out;
}

/**
 * Generate a formation for a canvas of w×h cells (short side is normally 4).
 * Deterministic for a given (w, h, seed, options).
 * Returns { w, h, r, seed, dots, lines } with dots in rank order, kernel first.
 */
function generate(w, h, seed, options = {}) {
  const o = { ...defaults, ...options };
  const rnd = rng(seed);
  const limX = w / 2 - R - o.edge;
  const limY = h / 2 - R - o.edge;

  // The kernel: edge passes through the crosshair, at any angle.
  // Its center is at distance exactly R — never on the center itself.
  const theta = rnd() * Math.PI * 2;
  const kernel = [R * Math.cos(theta), R * Math.sin(theta)];

  const minCenterDist = 2 * R + o.gap;
  const n = Math.max(1, Math.round(o.count)) - 1; // non-kernel dots

  let best = null;
  let bestScore = -Infinity;

  for (let roll = 0; roll < o.rollouts; roll++) {
    const cands = candidatePositions(limX, limY, o.placement, rnd);
    let maxD = 0;
    for (const c of cands) maxD = Math.max(maxD, len(c));
    const reach = Math.max(o.spread * maxD, R + n * o.rankStep + 0.01);

    const placed = [kernel];
    const used = new Set();
    let lastD = R;
    let missing = 0;
    let relaxed = 0;

    for (let m = 1; m <= n; m++) {
      const target = R + (m / n) * (reach - R); // evenly spaced gravity rings
      const pick = (step) => {
        let bi = -1;
        let bCost = Infinity;
        for (let c = 0; c < cands.length; c++) {
          if (used.has(c)) continue;
          const p = cands[c];
          const d = len(p);
          if (d < lastD + step) continue; // falloff must keep growing
          if (d < R + 1e-6) continue; //     nothing ever sits on the center
          let ok = true;
          for (const q of placed)
            if (dist(p, q) < minCenterDist) { ok = false; break; }
          if (!ok) continue;
          const cost = Math.abs(d - target) + 0.18 * rnd();
          if (cost < bCost) { bCost = cost; bi = c; }
        }
        return bi;
      };
      // strict growth first; where the lattice runs out of rings (e.g.
      // 'points' on a square canvas) allow same-distance ties before giving up
      let bi = pick(o.rankStep);
      if (bi === -1) {
        bi = pick(0);
        if (bi !== -1) relaxed++;
      }
      if (bi === -1) { missing++; continue; }
      used.add(bi);
      placed.push(cands[bi]);
      lastD = len(cands[bi]);
    }

    // Score: dots should surround the center (small resultant of unit
    // vectors), keep air between each other, and use the allowed reach.
    let res = [0, 0];
    let minGap = Infinity;
    for (let i = 0; i < placed.length; i++) {
      const d = len(placed[i]);
      res[0] += placed[i][0] / d;
      res[1] += placed[i][1] / d;
      for (let j = i + 1; j < placed.length; j++)
        minGap = Math.min(minGap, dist(placed[i], placed[j]) - 2 * R);
    }
    const balance = 1 - len(res) / placed.length;
    const score =
      balance +
      0.8 * Math.min(minGap, 0.5) +
      0.4 * Math.min(lastD / reach, 1) -
      0.6 * relaxed - // prefer a strictly graded falloff whenever one exists
      10 * missing;

    if (score > bestScore) {
      bestScore = score;
      best = placed;
    }
  }

  return { w, h, r: R, seed: String(seed), dots: best, lines: gridLines(w, h) };
}

/** Interior gridlines (integer offsets from center) for the overlay. */
function gridLines(w, h) {
  const v = [];
  const hh = [];
  for (let i = Math.ceil(-w / 2); i <= Math.floor(w / 2); i++)
    if (Math.abs(i) < w / 2 - 1e-9) v.push(i);
  for (let j = Math.ceil(-h / 2); j <= Math.floor(h / 2); j++)
    if (Math.abs(j) < h / 2 - 1e-9) hh.push(j);
  return { v, h: hh };
}

/**
 * Reorder a new formation's non-kernel dots so each existing circle travels
 * the least (sum of squared moves, brute force over 5! permutations).
 * Circle 0 is the kernel and keeps its role — it only ever orbits the center.
 * Returns a new dots array aligned to the current circles' indices.
 */
function assignTargets(current, target) {
  const nk = target.length - 1;
  const idx = Array.from({ length: nk }, (_, i) => i + 1);
  let bestPerm = idx.slice();
  let bestCost = Infinity;
  const d2 = (a, b) => {
    const dx = a[0] - b[0];
    const dy = a[1] - b[1];
    return dx * dx + dy * dy;
  };
  const permute = (arr, k) => {
    if (k === arr.length) {
      let cost = 0;
      for (let i = 0; i < arr.length; i++)
        cost += d2(current[i + 1], target[arr[i]]);
      if (cost < bestCost) { bestCost = cost; bestPerm = arr.slice(); }
      return;
    }
    for (let i = k; i < arr.length; i++) {
      [arr[k], arr[i]] = [arr[i], arr[k]];
      permute(arr, k + 1);
      [arr[k], arr[i]] = [arr[i], arr[k]];
    }
  };
  if (current && current.length === target.length && nk > 0) permute(idx.slice(), 0);
  const out = [target[0]];
  for (const p of bestPerm) out.push(target[p]);
  return out;
}

// ---- src/motion.js ----
// kzn-logo — shared motion math. Pure functions, no DOM: both the SVG and
// WebGL renderers move dots through exactly these paths.
//
// Two rules carry over from the mark's concept into motion itself:
//   · the kernel never leaves the crosshair — it orbits it, edge always in
//     contact, along the shorter arc
//   · no dot ever covers the center, even mid-flight — a straight path that
//     would sweep the crosshair bows around it instead


const EASINGS = {
  cubic: (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2),
  quint: (t) => (t < 0.5 ? 16 * t ** 5 : 1 - Math.pow(-2 * t + 2, 5) / 2),
  linear: (t) => t,
};

/** Orbit path for the kernel: angle lerps along the shorter arc, radius R→R. */
function kernelPath(a, b) {
  const a0 = Math.atan2(a[1], a[0]);
  let da = Math.atan2(b[1], b[0]) - a0;
  if (da > Math.PI) da -= 2 * Math.PI;
  if (da < -Math.PI) da += 2 * Math.PI;
  const r0 = Math.hypot(a[0], a[1]) || R;
  const r1 = Math.hypot(b[0], b[1]) || R;
  return (t) => {
    const ang = a0 + da * t;
    const rr = r0 + (r1 - r0) * t;
    return [rr * Math.cos(ang), rr * Math.sin(ang)];
  };
}

/** Straight path — bowed around the crosshair when it would sweep it. */
function dotPath(a, b) {
  const clearance = R + 0.1;
  const near = segNearestToOrigin(a, b);
  const nl = Math.hypot(near[0], near[1]);
  if (nl >= clearance) {
    return (t) => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
  }
  // push the control point along the origin→segment shortest vector — that is
  // perpendicular to the travel, so the curve actually swerves sideways
  let dx = near[0];
  let dy = near[1];
  let dl = nl;
  if (dl < 1e-4) {
    dx = -(b[1] - a[1]);
    dy = b[0] - a[0];
    dl = Math.hypot(dx, dy) || 1;
  }
  const push = 2 * clearance + R; // control point far enough to clear center
  const cx = (dx / dl) * push;
  const cy = (dy / dl) * push;
  return (t) => {
    const u = 1 - t;
    return [
      u * u * a[0] + 2 * u * t * cx + t * t * b[0],
      u * u * a[1] + 2 * u * t * cy + t * t * b[1],
    ];
  };
}

function segNearestToOrigin(a, b) {
  const abx = b[0] - a[0];
  const aby = b[1] - a[1];
  const l2 = abx * abx + aby * aby;
  if (l2 < 1e-12) return [a[0], a[1]];
  let t = -(a[0] * abx + a[1] * aby) / l2;
  t = Math.max(0, Math.min(1, t));
  return [a[0] + t * abx, a[1] + t * aby];
}

/**
 * Build per-dot tweens from current positions to targets (index 0 = kernel).
 * `now` is the caller's clock so renderers stay testable.
 */
function buildTweens(current, targets, { duration, stagger }, now) {
  return targets.map((to, i) => {
    const from = current[i] ?? to;
    const path = i === 0 ? kernelPath(from, to) : dotPath(from, to);
    return {
      path,
      t0: now + (i === 0 ? 0 : i * stagger),
      dur: duration,
      done: false,
    };
  });
}

/**
 * Sample all tweens at `now`. Returns { pts, live }: positions per dot and
 * whether anything is still in flight. Marks finished tweens done.
 */
function sampleTweens(anims, now, easing) {
  const ease = EASINGS[easing] || EASINGS.cubic;
  const pts = new Array(anims.length);
  let live = false;
  for (let i = 0; i < anims.length; i++) {
    const a = anims[i];
    let t = (now - a.t0) / a.dur;
    if (t < 1) live = true;
    else {
      t = 1;
      a.done = true;
    }
    pts[i] = a.path(t <= 0 ? 0 : ease(t));
  }
  return { pts, live };
}

// ---- src/svg.js ----
// kzn-logo — flat SVG renderer + animator. No dependencies.
//
// Renders formations from core.js as plain <circle> elements (the dot IS a
// mathematical circle — generating it keeps geometry as data, stays crisp at
// any scale and DPR, and the same data feeds the WebGL treatment).
// Fill is `currentColor`, so the consumer sets the ink with CSS `color`.



const SVG_NS = 'http://www.w3.org/2000/svg';

/** Render the canonical static mark into an <svg> element. */
function renderMark(svg) {
  const [x, y, w, h] = MARK.viewBox;
  svg.setAttribute('viewBox', `${x} ${y} ${w} ${h}`);
  svg.setAttribute('preserveAspectRatio', 'xMidYMid meet');
  svg.textContent = '';
  for (const [cx, cy] of MARK.dots) {
    const c = document.createElementNS(SVG_NS, 'circle');
    c.setAttribute('cx', cx);
    c.setAttribute('cy', cy);
    c.setAttribute('r', MARK.r);
    c.setAttribute('fill', 'currentColor');
    svg.appendChild(c);
  }
}

/** Standalone SVG markup for export/download (static mark or a formation). */
function toSVG(formationOrMark, { ink = '#1E1E1E', size = 640 } = {}) {
  let vb, r, dots;
  if (formationOrMark.viewBox) {
    const m = formationOrMark;
    vb = m.viewBox;
    r = m.r;
    dots = m.dots;
  } else {
    const f = formationOrMark;
    vb = [-f.w / 2, -f.h / 2, f.w, f.h];
    r = f.r;
    dots = f.dots;
  }
  const [x, y, w, h] = vb;
  const height = Math.round((size * h) / w);
  const circles = dots
    .map(([cx, cy]) => `  <circle cx="${fmt(cx)}" cy="${fmt(cy)}" r="${fmt(r)}" fill="${ink}"/>`)
    .join('\n');
  return `<svg xmlns="${SVG_NS}" viewBox="${fmt(x)} ${fmt(y)} ${fmt(w)} ${fmt(h)}" width="${size}" height="${height}">\n${circles}\n</svg>\n`;
}

const fmt = (n) => (Math.round(n * 10000) / 10000).toString();

/**
 * Dynamic renderer. Owns the circles + the construction-grid overlay inside
 * one <svg>, and animates between formations at display refresh rate.
 * All motion is a single rAF loop mutating cx/cy — a handful of circles,
 * no layout work, no framework.
 */
function createDynamicRenderer(svg, opts = {}) {
  const state = {
    duration: opts.duration ?? 750,
    stagger: opts.stagger ?? 45,
    easing: opts.easing ?? 'cubic',
    motion: opts.motion ?? 'glide', // 'glide' | 'instant'
    reduced:
      typeof matchMedia === 'function' &&
      matchMedia('(prefers-reduced-motion: reduce)').matches,
    formation: null,
    circles: [],
    current: [], // live [x, y] per circle
    anims: null,
    raf: 0,
    onSettle: null,
  };

  svg.setAttribute('preserveAspectRatio', 'xMidYMid meet');
  const gridG = document.createElementNS(SVG_NS, 'g');
  gridG.setAttribute('stroke', 'currentColor');
  gridG.setAttribute('stroke-opacity', '0.18');
  gridG.setAttribute('display', 'none');
  const dotsG = document.createElementNS(SVG_NS, 'g');
  svg.append(gridG, dotsG);

  function ensureCircles(n) {
    while (state.circles.length < n) {
      const c = document.createElementNS(SVG_NS, 'circle');
      c.setAttribute('fill', 'currentColor');
      dotsG.appendChild(c);
      state.circles.push(c);
    }
    while (state.circles.length > n) state.circles.pop().remove();
  }

  function drawGrid(f) {
    gridG.textContent = '';
    const strokeW = Math.max(f.w, f.h) / 420; // hairline at any scale
    gridG.setAttribute('stroke-width', strokeW);
    const line = (x1, y1, x2, y2) => {
      const l = document.createElementNS(SVG_NS, 'line');
      l.setAttribute('x1', x1);
      l.setAttribute('y1', y1);
      l.setAttribute('x2', x2);
      l.setAttribute('y2', y2);
      gridG.appendChild(l);
    };
    for (const i of f.lines.v) line(i, -f.h / 2, i, f.h / 2);
    for (const j of f.lines.h) line(-f.w / 2, j, f.w / 2, j);
    // the crosshair itself, slightly more present
    const cross = document.createElementNS(SVG_NS, 'circle');
    cross.setAttribute('r', strokeW * 2.4);
    cross.setAttribute('cx', 0);
    cross.setAttribute('cy', 0);
    cross.setAttribute('fill', 'currentColor');
    cross.setAttribute('fill-opacity', '0.5');
    cross.setAttribute('stroke', 'none');
    gridG.appendChild(cross);
  }

  function put(i, x, y) {
    state.current[i] = [x, y];
    const c = state.circles[i];
    c.setAttribute('cx', x);
    c.setAttribute('cy', y);
  }

  function tick(now) {
    state.raf = 0;
    if (!state.anims) return;
    const { pts, live } = sampleTweens(state.anims, now, state.easing);
    pts.forEach(([x, y], i) => put(i, x, y));
    if (live) state.raf = requestAnimationFrame(tick);
    else {
      state.anims = null;
      state.onSettle?.();
    }
  }

  return {
    /** Move to a formation. Animates from wherever the dots are right now. */
    setFormation(f, { animate = true } = {}) {
      const first = !state.formation;
      state.formation = f;
      svg.setAttribute('viewBox', `${-f.w / 2} ${-f.h / 2} ${f.w} ${f.h}`);
      drawGrid(f);
      ensureCircles(f.dots.length);
      for (const c of state.circles) c.setAttribute('r', f.r);

      const instant =
        first ||
        !animate ||
        state.reduced ||
        state.motion === 'instant' ||
        state.duration <= 0;

      const targets = first ? f.dots : assignTargets(state.current, f.dots);

      if (instant) {
        if (state.raf) cancelAnimationFrame(state.raf);
        state.anims = null;
        targets.forEach(([x, y], i) => put(i, x, y));
        state.onSettle?.();
        return;
      }

      state.anims = buildTweens(state.current, targets, state, performance.now());
      if (!state.raf) state.raf = requestAnimationFrame(tick);
    },
    showGrid(on) {
      gridG.setAttribute('display', on ? 'inline' : 'none');
    },
    configure(patch) {
      Object.assign(state, patch);
    },
    resizePx() {}, // SVG scales by itself
    get formation() {
      return state.formation;
    },
    get settled() {
      return !state.anims;
    },
    set onSettle(fn) {
      state.onSettle = fn;
    },
    destroy() {
      if (state.raf) cancelAnimationFrame(state.raf);
      svg.textContent = '';
    },
  };
}

// ---- src/webgl.js ----
// kzn-logo — WebGL2 renderer. Same contract as the SVG dynamic renderer,
// same formations, same motion math — plus a post-processing pipeline for
// the treated look (page backgrounds, hero moments).
//
// With every effect at 0 the output is pixel-parity with the flat SVG:
// antialiased currentColor dots on transparency, straight to screen.
// The effect passes below (blur → grain → duotone) are SCAFFOLD placeholders
// wired end-to-end so the real stack — replicated from the Unicorn Studio
// prototype — can land as shader work without touching the engine.
//
// Perf posture: fragment SDF over ≤8 dots (no geometry), half-resolution
// blur chain, renders only while something changes (tween or animated
// grain), DPR capped at 2.



const VS = `#version 300 es
void main() {
  vec2 v = vec2(float((gl_VertexID << 1) & 2), float(gl_VertexID & 2));
  gl_Position = vec4(v * 2.0 - 1.0, 0.0, 1.0);
}`;

// dots + construction grid, drawn as one signed-distance field
const SCENE_FS = `#version 300 es
precision highp float;
uniform vec2 uRes;      // px
uniform vec2 uHalf;     // canvas half-size, in cells
uniform vec3 uDots[8];  // x, y (cells, center origin, y down), radius
uniform int uCount;
uniform vec4 uInk;
uniform vec4 uBg;
uniform float uOpaque;  // 1 = composite on uBg (effects), 0 = transparent
uniform float uGrid;
out vec4 outColor;
void main() {
  vec2 uv = gl_FragCoord.xy / uRes * 2.0 - 1.0;
  vec2 p = vec2(uv.x * uHalf.x, -uv.y * uHalf.y);
  float pxPerCell = uRes.x / (2.0 * uHalf.x);
  float aa = 1.0 / pxPerCell;

  float cov = 0.0;
  for (int i = 0; i < 8; i++) {
    if (i >= uCount) break;
    float d = length(p - uDots[i].xy) - uDots[i].z;
    cov = max(cov, 1.0 - smoothstep(-aa, aa, d));
  }

  float a = cov;
  if (uGrid > 0.5) {
    float lw = max(uHalf.x, uHalf.y) * 2.0 / 420.0; // hairline, as in SVG
    vec2 nearest = vec2(floor(p.x + 0.5), floor(p.y + 0.5));
    vec2 dist = abs(p - nearest);
    float lx = (abs(nearest.x) <= uHalf.x - 0.001)
      ? 1.0 - smoothstep(lw * 0.5, lw * 0.5 + aa, dist.x) : 0.0;
    float ly = (abs(nearest.y) <= uHalf.y - 0.001)
      ? 1.0 - smoothstep(lw * 0.5, lw * 0.5 + aa, dist.y) : 0.0;
    float cross = (1.0 - smoothstep(lw * 2.4, lw * 2.4 + aa, length(p))) * 0.5;
    a = max(a, max(max(lx, ly) * 0.18, cross));
  }

  if (uOpaque > 0.5) {
    outColor = vec4(mix(uBg.rgb, uInk.rgb, a), 1.0);
  } else {
    outColor = vec4(uInk.rgb * a, a); // premultiplied
  }
}`;

const BLUR_FS = `#version 300 es
precision highp float;
uniform sampler2D uTex;
uniform vec2 uRes;    // px of the target
uniform vec2 uDir;
uniform float uRadius;
out vec4 outColor;
void main() {
  vec2 uv = gl_FragCoord.xy / uRes;
  vec2 s = uDir * (uRadius / 4.0) / uRes;
  vec4 c = texture(uTex, uv) * 0.2026;
  c += (texture(uTex, uv + s * 1.0) + texture(uTex, uv - s * 1.0)) * 0.1790;
  c += (texture(uTex, uv + s * 2.0) + texture(uTex, uv - s * 2.0)) * 0.1240;
  c += (texture(uTex, uv + s * 3.0) + texture(uTex, uv - s * 3.0)) * 0.0672;
  c += (texture(uTex, uv + s * 4.0) + texture(uTex, uv - s * 4.0)) * 0.0285;
  outColor = c;
}`;

const POST_FS = `#version 300 es
precision highp float;
uniform sampler2D uTex;
uniform vec2 uRes;
uniform float uGrain;
uniform float uTime;
uniform float uTintAmt;
uniform vec3 uTintInk;  // tone the dots drift toward
uniform vec3 uTintBg;   // tone the ground drifts toward
out vec4 outColor;
void main() {
  vec2 uv = gl_FragCoord.xy / uRes;
  vec4 c = texture(uTex, uv);
  float lum = dot(c.rgb, vec3(0.299, 0.587, 0.114));
  c.rgb = mix(c.rgb, mix(uTintInk, uTintBg, lum), uTintAmt);
  vec2 cell = floor(gl_FragCoord.xy) + vec2(uTime * 60.0, uTime * 47.0);
  float n = fract(sin(dot(cell, vec2(12.9898, 78.233))) * 43758.5453);
  c.rgb += (n - 0.5) * uGrain;
  outColor = vec4(c.rgb, 1.0);
}`;

/** '#rrggbb' | 'rgb(a)' string → [r,g,b,a] in 0..1 */
function parseColor(str) {
  if (!str) return [0, 0, 0, 1];
  str = str.trim();
  if (str[0] === '#') {
    const h = str.slice(1);
    const n = parseInt(h.length === 3 ? [...h].map((c) => c + c).join('') : h, 16);
    return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255, 1];
  }
  const m = str.match(/rgba?\(([^)]+)\)/);
  if (!m) return [0, 0, 0, 1];
  const v = m[1].split(',').map(parseFloat);
  return [v[0] / 255, v[1] / 255, v[2] / 255, v.length > 3 ? v[3] : 1];
}

function createWebGLRenderer(canvas, host, opts = {}) {
  const gl = canvas.getContext('webgl2', {
    alpha: true,
    premultipliedAlpha: true,
    antialias: false,
    depth: false,
    stencil: false,
  });
  if (!gl) return null;

  function compile(fsSrc) {
    const p = gl.createProgram();
    for (const [type, src] of [
      [gl.VERTEX_SHADER, VS],
      [gl.FRAGMENT_SHADER, fsSrc],
    ]) {
      const s = gl.createShader(type);
      gl.shaderSource(s, src);
      gl.compileShader(s);
      if (!gl.getShaderParameter(s, gl.COMPILE_STATUS))
        throw new Error('kzn-logo shader: ' + gl.getShaderInfoLog(s));
      gl.attachShader(p, s);
    }
    gl.linkProgram(p);
    if (!gl.getProgramParameter(p, gl.LINK_STATUS))
      throw new Error('kzn-logo link: ' + gl.getProgramInfoLog(p));
    const uniforms = {};
    const n = gl.getProgramParameter(p, gl.ACTIVE_UNIFORMS);
    for (let i = 0; i < n; i++) {
      const info = gl.getActiveUniform(p, i);
      uniforms[info.name.replace(/\[0\]$/, '')] = gl.getUniformLocation(p, info.name);
    }
    return { p, u: uniforms };
  }

  const scene = compile(SCENE_FS);
  const blur = compile(BLUR_FS);
  const post = compile(POST_FS);

  const state = {
    duration: opts.duration ?? 750,
    stagger: opts.stagger ?? 45,
    easing: opts.easing ?? 'cubic',
    motion: opts.motion ?? 'glide',
    reduced:
      typeof matchMedia === 'function' &&
      matchMedia('(prefers-reduced-motion: reduce)').matches,
    formation: null,
    current: [],
    anims: null,
    raf: 0,
    gridOn: false,
    onSettle: null,
    ink: [0.12, 0.12, 0.12, 1],
    bg: [1, 0.984, 0.973, 1],
    effects: { blur: 0, grain: 0, tint: 0, tintColor: '#AFA8D8', background: null },
    pxW: 0,
    pxH: 0,
    t0: performance.now(),
  };

  // --- framebuffers -------------------------------------------------------
  let texScene = null, fboScene = null;
  let texA = null, fboA = null, texB = null, fboB = null;

  function makeTarget(w, h) {
    const t = gl.createTexture();
    gl.bindTexture(gl.TEXTURE_2D, t);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, w, h, 0, gl.RGBA, gl.UNSIGNED_BYTE, null);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    const f = gl.createFramebuffer();
    gl.bindFramebuffer(gl.FRAMEBUFFER, f);
    gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, t, 0);
    return [t, f];
  }

  function allocTargets() {
    for (const t of [texScene, texA, texB]) if (t) gl.deleteTexture(t);
    for (const f of [fboScene, fboA, fboB]) if (f) gl.deleteFramebuffer(f);
    [texScene, fboScene] = makeTarget(state.pxW, state.pxH);
    const hw = Math.max(1, state.pxW >> 1);
    const hh = Math.max(1, state.pxH >> 1);
    [texA, fboA] = makeTarget(hw, hh);
    [texB, fboB] = makeTarget(hw, hh);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
  }

  // --- drawing ------------------------------------------------------------
  const effectsActive = () =>
    state.effects.blur > 0 || state.effects.grain > 0 || state.effects.tint > 0;

  function drawScene(opaque) {
    const f = state.formation;
    gl.useProgram(scene.p);
    gl.uniform2f(scene.u.uRes, gl.drawingBufferWidth, gl.drawingBufferHeight);
    gl.uniform2f(scene.u.uHalf, f.w / 2, f.h / 2);
    const flat = new Float32Array(24);
    const n = Math.min(state.current.length, 8);
    for (let i = 0; i < n; i++) {
      flat[i * 3] = state.current[i][0];
      flat[i * 3 + 1] = state.current[i][1];
      flat[i * 3 + 2] = f.r;
    }
    gl.uniform3fv(scene.u.uDots, flat);
    gl.uniform1i(scene.u.uCount, n);
    gl.uniform4fv(scene.u.uInk, state.ink);
    gl.uniform4fv(scene.u.uBg, state.bg);
    gl.uniform1f(scene.u.uOpaque, opaque ? 1 : 0);
    gl.uniform1f(scene.u.uGrid, state.gridOn ? 1 : 0);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
  }

  function blurPass(fbo, w, h, tex, dirX, dirY, radius) {
    gl.bindFramebuffer(gl.FRAMEBUFFER, fbo);
    gl.viewport(0, 0, w, h);
    gl.useProgram(blur.p);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, tex);
    gl.uniform1i(blur.u.uTex, 0);
    gl.uniform2f(blur.u.uRes, w, h);
    gl.uniform2f(blur.u.uDir, dirX, dirY);
    gl.uniform1f(blur.u.uRadius, radius);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
  }

  function draw() {
    if (!state.formation || !state.pxW) return;
    if (!effectsActive()) {
      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
      gl.viewport(0, 0, state.pxW, state.pxH);
      gl.clearColor(0, 0, 0, 0);
      gl.clear(gl.COLOR_BUFFER_BIT);
      drawScene(false);
      return;
    }
    // scene → full-res texture, composited on the ground color
    gl.bindFramebuffer(gl.FRAMEBUFFER, fboScene);
    gl.viewport(0, 0, state.pxW, state.pxH);
    drawScene(true);

    // blur chain at half res
    const hw = Math.max(1, state.pxW >> 1);
    const hh = Math.max(1, state.pxH >> 1);
    let tex = texScene;
    const r = state.effects.blur / 2; // half-res space
    if (state.effects.blur > 0) {
      const rounds = state.effects.blur > 40 ? 2 : 1;
      for (let i = 0; i < rounds; i++) {
        blurPass(fboA, hw, hh, tex, 1, 0, r / rounds);
        blurPass(fboB, hw, hh, texA, 0, 1, r / rounds);
        tex = texB;
      }
    }

    // post: grain + duotone, to screen
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    gl.viewport(0, 0, state.pxW, state.pxH);
    gl.useProgram(post.p);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, tex);
    gl.uniform1i(post.u.uTex, 0);
    gl.uniform2f(post.u.uRes, state.pxW, state.pxH);
    gl.uniform1f(post.u.uGrain, state.effects.grain);
    gl.uniform1f(
      post.u.uTime,
      state.reduced ? 0 : (performance.now() - state.t0) / 1000
    );
    gl.uniform1f(post.u.uTintAmt, state.effects.tint);
    const tc = parseColor(state.effects.tintColor);
    gl.uniform3f(post.u.uTintInk, tc[0], tc[1], tc[2]);
    gl.uniform3f(post.u.uTintBg, state.bg[0], state.bg[1], state.bg[2]);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
  }

  // --- loop ---------------------------------------------------------------
  const needsLoop = () =>
    !!state.anims || (state.effects.grain > 0 && !state.reduced);

  function tick(now) {
    state.raf = 0;
    if (state.anims) {
      const { pts, live } = sampleTweens(state.anims, now, state.easing);
      state.current = pts;
      if (!live) {
        state.anims = null;
        state.onSettle?.();
      }
    }
    draw();
    if (needsLoop()) state.raf = requestAnimationFrame(tick);
  }

  function ensureLoop() {
    if (!state.raf && needsLoop()) state.raf = requestAnimationFrame(tick);
  }

  function readColors() {
    if (typeof getComputedStyle !== 'function') return;
    const cs = getComputedStyle(host);
    state.ink = parseColor(cs.color);
    const bgStr =
      state.effects.background ||
      (() => {
        let el = host;
        while (el) {
          const b = getComputedStyle(el).backgroundColor;
          if (b && !b.startsWith('rgba(0, 0, 0, 0)')) return b;
          el = el.parentElement;
        }
        return document.body ? getComputedStyle(document.body).backgroundColor : '#fff';
      })();
    state.bg = parseColor(bgStr);
  }

  readColors();

  return {
    setFormation(f, { animate = true } = {}) {
      const first = !state.formation;
      state.formation = f;
      readColors();
      const instant =
        first ||
        !animate ||
        state.reduced ||
        state.motion === 'instant' ||
        state.duration <= 0;
      const targets = first ? f.dots : assignTargets(state.current, f.dots);
      if (instant) {
        state.anims = null;
        state.current = targets.map((d) => d.slice());
        draw();
        state.onSettle?.();
      } else {
        state.anims = buildTweens(state.current, targets, state, performance.now());
        ensureLoop();
      }
      ensureLoop();
    },
    showGrid(on) {
      state.gridOn = !!on;
      draw();
    },
    configure(patch) {
      Object.assign(state, patch);
      readColors();
      draw();
    },
    setEffects(patch) {
      Object.assign(state.effects, patch);
      readColors();
      draw();
      ensureLoop();
    },
    refreshInk() {
      readColors();
      draw();
    },
    resizePx(cssW, cssH, dpr) {
      const scale = Math.min(dpr || 1, 2);
      const w = Math.max(1, Math.round(cssW * scale));
      const h = Math.max(1, Math.round(cssH * scale));
      if (w === state.pxW && h === state.pxH) return;
      state.pxW = w;
      state.pxH = h;
      canvas.width = w;
      canvas.height = h;
      allocTargets();
      draw();
    },
    get formation() {
      return state.formation;
    },
    get settled() {
      return !state.anims;
    },
    set onSettle(fn) {
      state.onSettle = fn;
    },
    destroy() {
      if (state.raf) cancelAnimationFrame(state.raf);
      gl.getExtension('WEBGL_lose_context')?.loseContext();
    },
  };
}

// ---- src/element.js ----
// kzn-logo — <kzn-logo> custom element. Framework-agnostic: drop the script on
// any page (plain HTML, React, Vue, ...) and use the tag.
//
//   <kzn-logo mode="static"></kzn-logo>                     the stable symbol
//   <kzn-logo mode="dynamic" interactive seed="kzn"></kzn-logo>
//
// Sizing is the host's business (CSS width/height); ink is CSS `color`.




const BASE_CELLS = 4; // cells on the short side — the 4×4 heritage

class KznLogo extends HTMLElement {
  static observedAttributes = ['mode', 'seed', 'grid', 'interactive', 'renderer'];

  #svg = null;
  #canvas = null;
  #dyn = null;
  #ro = null;
  #dims = null; // { w, h } in cells
  #base = null; // seed base
  #step = 0; //   0 = the ideal mark; n>0 = generated formation n
  #engineOpts = {};
  #effectsOpts = null;
  #resizeTimer = 0;

  constructor() {
    super();
    const root = this.attachShadow({ mode: 'open' });
    const style = document.createElement('style');
    style.textContent =
      ':host{display:block;color:inherit}:host([interactive]){cursor:pointer}' +
      'svg,canvas{display:block;width:100%;height:100%}' +
      '[hidden]{display:none !important}';
    this.#svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    this.#svg.setAttribute('aria-hidden', 'true');
    root.append(style, this.#svg);
  }

  connectedCallback() {
    if (!this.hasAttribute('role')) this.setAttribute('role', 'img');
    if (!this.hasAttribute('aria-label'))
      this.setAttribute('aria-label', 'Kaizen logo');
    this.#base = this.getAttribute('seed') || Math.random().toString(36).slice(2, 8);
    if (this.hasAttribute('interactive')) this.setAttribute('tabindex', '0');
    this.addEventListener('click', this.#onClick);
    this.addEventListener('keydown', this.#onKey);
    this.#mount();
  }

  disconnectedCallback() {
    this.removeEventListener('click', this.#onClick);
    this.removeEventListener('keydown', this.#onKey);
    this.#unmount();
  }

  attributeChangedCallback(name, oldV, newV) {
    if (oldV === newV || !this.isConnected) return;
    if (name === 'mode') this.#mount();
    else if (name === 'seed') {
      this.#base = newV || this.#base;
      this.#step = 0;
      this.#apply(true);
    } else if (name === 'grid') this.#dyn?.showGrid(newV !== null);
    else if (name === 'renderer') this.#mount();
    else if (name === 'interactive') {
      if (newV !== null) this.setAttribute('tabindex', '0');
      else this.removeAttribute('tabindex');
    }
  }

  get mode() {
    return this.getAttribute('mode') === 'dynamic' ? 'dynamic' : 'static';
  }

  /** Engine + motion options; merged, live. See core.defaults and svg renderer. */
  set options(patch) {
    const motion = {};
    for (const k of ['duration', 'stagger', 'easing', 'motion'])
      if (k in patch) motion[k] = patch[k];
    for (const k of ['placement', 'gap', 'spread', 'edge', 'rankStep', 'count', 'rollouts'])
      if (k in patch) this.#engineOpts[k] = patch[k];
    this.#dyn?.configure(motion);
    if (Object.keys(patch).some((k) => k in this.#engineOpts) && this.#step > 0)
      this.#apply(true);
  }

  /** Advance to the next formation (or restart from a given seed). */
  shuffle(seed) {
    if (this.mode !== 'dynamic') return;
    if (seed !== undefined) {
      this.#base = String(seed);
      this.#step = 1;
    } else this.#step++;
    this.#apply(true);
  }

  /** Back to the resting state: the ideal mark on the current canvas. */
  rest() {
    this.#step = 0;
    this.#apply(true);
  }

  /**
   * Post-effect parameters (WebGL renderer only; ignored by SVG):
   * { blur: px, grain: 0..1, tint: 0..1, tintColor: '#…', background: '#…' }.
   * All zero by default — flat parity. Placeholder stack until the Unicorn
   * Studio effect chain is replicated.
   */
  set effects(patch) {
    this.#effectsOpts = { ...(this.#effectsOpts || {}), ...patch };
    this.#dyn?.setEffects?.(this.#effectsOpts);
  }

  get effects() {
    return this.#effectsOpts;
  }

  /** Re-read CSS ink/ground colors (call after a theme change). */
  refreshInk() {
    this.#dyn?.refreshInk?.();
  }

  get formation() {
    return this.mode === 'dynamic' ? this.#dyn?.formation : MARK;
  }

  get seed() {
    return this.#step === 0 ? 'mark' : `${this.#base}#${this.#step}`;
  }

  /** Standalone SVG markup of what is currently shown (for export). */
  exportSVG(opts) {
    const f = this.mode === 'dynamic' ? this.#dyn?.formation : MARK;
    return toSVG(f || MARK, opts);
  }

  // --- internals ---------------------------------------------------------

  #onClick = () => {
    if (this.hasAttribute('interactive')) this.shuffle();
  };

  #onKey = (e) => {
    if (!this.hasAttribute('interactive')) return;
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      this.shuffle();
    }
  };

  #mount() {
    this.#unmount();
    if (this.mode === 'static') {
      this.#svg.toggleAttribute('hidden', false);
      renderMark(this.#svg);
      return;
    }
    // dynamic: WebGL when asked for and available, flat SVG otherwise.
    // A fresh canvas per mount — a lost/destroyed context can't be revived.
    if (this.getAttribute('renderer') === 'webgl') {
      this.#canvas = document.createElement('canvas');
      this.#canvas.setAttribute('aria-hidden', 'true');
      this.shadowRoot.append(this.#canvas);
      try {
        this.#dyn = createWebGLRenderer(this.#canvas, this);
      } catch {
        this.#dyn = null;
      }
      if (!this.#dyn) {
        this.#canvas.remove();
        this.#canvas = null;
      }
    }
    const usingGL = !!this.#dyn;
    if (!usingGL) this.#dyn = createDynamicRenderer(this.#svg);
    this.#svg.toggleAttribute('hidden', usingGL);
    this.dataset.rendererActive = usingGL ? 'webgl' : 'svg';
    if (usingGL && this.#effectsOpts) this.#dyn.setEffects(this.#effectsOpts);

    this.#dyn.onSettle = () =>
      this.dispatchEvent(
        new CustomEvent('kzn-settle', { bubbles: true, composed: true })
      );
    this.#ro = new ResizeObserver((entries) => {
      const r = entries[entries.length - 1].contentRect;
      if (r.width < 1 || r.height < 1) return;
      this.#dyn?.resizePx?.(r.width, r.height, window.devicePixelRatio || 1);
      const ar = r.width / r.height;
      const w = ar >= 1 ? BASE_CELLS * ar : BASE_CELLS;
      const h = ar >= 1 ? BASE_CELLS : BASE_CELLS / ar;
      const prev = this.#dims;
      this.#dims = { w, h };
      if (!prev) {
        this.#apply(false); // first layout: paint instantly
      } else if (Math.abs(prev.w - w) > 0.02 || Math.abs(prev.h - h) > 0.02) {
        clearTimeout(this.#resizeTimer);
        this.#resizeTimer = setTimeout(() => this.#apply(true), 90);
      }
    });
    this.#ro.observe(this);
  }

  #unmount() {
    this.#ro?.disconnect();
    this.#ro = null;
    clearTimeout(this.#resizeTimer);
    this.#dyn?.destroy();
    this.#dyn = null;
    this.#dims = null;
    this.#svg.textContent = '';
    this.#canvas?.remove();
    this.#canvas = null;
    delete this.dataset.rendererActive;
  }

  #formationForStep() {
    const { w, h } = this.#dims;
    if (this.#step === 0)
      return {
        w,
        h,
        r: R,
        seed: 'mark',
        dots: MARK_IDEAL.dots.map((d) => d.slice()),
        lines: gridLines(w, h),
      };
    return generate(w, h, `${this.#base}#${this.#step}`, this.#engineOpts);
  }

  #apply(animate) {
    if (this.mode !== 'dynamic' || !this.#dyn || !this.#dims) return;
    const f = this.#formationForStep();
    this.#dyn.setFormation(f, { animate });
    this.#dyn.showGrid(this.hasAttribute('grid'));
    this.dispatchEvent(
      new CustomEvent('kzn-shuffle', {
        bubbles: true,
        composed: true,
        detail: { formation: f, step: this.#step, seed: this.seed },
      })
    );
  }
}

if (!customElements.get('kzn-logo')) customElements.define('kzn-logo', KznLogo);
